/**
 * SmartSales Web Widget - embeddable "Support Assistant" chat widget.
 *
 * Deliberately vanilla TypeScript (no React/Preact) rendered into a Shadow
 * DOM: this script runs on a THIRD-PARTY tenant website, not inside
 * supercontact-web itself, so it must not bloat the host page's bundle or
 * collide with whatever framework/CSS that page already uses. See plans/
 * for the full architecture rationale.
 *
 * Reads its own <script data-widget-key="..." data-api-url="..."> tag via
 * document.currentScript - both attributes are generated by the tenant's
 * Settings > Web Widget page (WebWidgetEmbedGuide.tsx) at copy time, so
 * this bundle itself never hardcodes an environment.
 *
 * UI/UX: a small view state machine (home <-> chat). The RENDER layer was
 * redesigned for the Support Assistant concept (home screen, quick-action
 * cards, human handoff, presence, privacy footer, mobile full-screen); the
 * transport/resilience layer (config fetch, localStorage session, REST
 * /start + /messages with idempotency + optimistic send/retry, receive-only
 * WS with backoff+jitter reconnect, ping/pong, dedupe, resync, 401 purge,
 * 1008 stop, direction inversion, unread badge, title flash, a11y, shadow
 * isolation) is preserved verbatim.
 */

interface QuickAction {
  id: string;
  label: string;
  description?: string | null;
  icon?: string | null;
  target_queue_id?: string | null;
  prefill?: string | null;
}

interface WidgetPresence {
  online: boolean;
  count: number;
  avatars: string[];
}

interface WidgetConfig {
  title: string;
  greeting_message: string;
  brand_color: string;
  is_widget_enabled: boolean;
  is_within_business_hours: boolean;
  offline_message?: string | null;

  // Support Assistant concept fields (added to GET /public/widget/config/{key}).
  bot_name?: string | null;
  bot_avatar_url?: string | null;
  home_headline?: string | null;
  home_subtext?: string | null;
  show_home_screen?: boolean;
  quick_actions?: QuickAction[] | null;
  response_time_label?: string | null;
  show_presence?: boolean;
  enable_human_handoff?: boolean;
  handoff_label?: string | null;
  handoff_queue_id?: string | null;
  privacy_footer_text?: string | null;
  privacy_url?: string | null;
  presence?: WidgetPresence | null;

  // AI Answer Bot (Phase 7B) - the PUBLIC subset of the tenant's answer-bot
  // config (get_public_config omits answer_bot_min_confidence, which is
  // server-side only). In 7B.1 the bot's reply arrives as a normal OUTBOUND
  // message and renders as a team bubble, so these fields need no new render
  // branch today - they're declared so a later 7B.2 rich card can consume them.
  answer_bot_enabled?: boolean;
  answer_bot_max_articles?: number;
  answer_bot_use_llm?: boolean;
  answer_bot_intro_text?: string | null;
  answer_bot_no_answer_text?: string | null;

  // i18n (POLISH sprint): the public config endpoint does NOT currently
  // return these, so today they're always undefined and the widget falls
  // back to the data-locale attribute (default "id"). Kept optional so that
  // IF the backend ever adds a `locale`/`strings` field to get_public_config
  // it's picked up with zero further frontend change - see resolveStrings().
  locale?: "id" | "en" | string | null;
  strings?: Partial<WidgetStrings> | null;
}

