// Base pack selected by locale (default Indonesian - the product's tenants
// are Indonesian), then merged with any per-string overrides (only ever
// present if the backend later supplies config.strings).
function resolveStrings(
  locale: string | null | undefined,
  overrides?: Partial<WidgetStrings> | null,
): WidgetStrings {
  const base = locale === "en" ? STRINGS_EN : STRINGS_ID;
  const merged: WidgetStrings = { ...base };
  if (overrides) {
    for (const k in overrides) {
      const v = (overrides as Record<string, unknown>)[k];
      if (typeof v === "string" && v.trim()) (merged as unknown as Record<string, string>)[k] = v;
    }
  }
  return merged;
}

interface StoredSession {
  visitor_token: string;
  conversation_id: string;
}

interface WidgetAttachment {
  filename?: string | null;
  content_type?: string | null;
  media_url: string;
  is_inline?: boolean;
}

interface WidgetMessage {
  id?: string;
  direction: "inbound" | "outbound";
  content: string;
  sent_at?: string;
  media_url?: string | null;
  attachments?: WidgetAttachment[];
  // Client-only bookkeeping (never sent to the server):
  client_message_id?: string; // idempotency key so a retry can't double-post
  status?: "sending" | "sent" | "failed";
  // Routing context captured at conversation start so a retry re-POSTs the
  // SAME /start payload (queue + originating quick-action). Anonymous start:
  // no visitor_name/visitor_email captured up-front anymore.
  startCtx?: { target_queue_id?: string | null; action_id?: string | null };
}

// Server-shaped message as returned by GET /public/widget/conversation and
// the WS "message" frame. NOTE the direction inversion vs the widget UI:
// the backend is company-centric (visitor = "inbound", agent = "outbound"),
// but the visitor-facing bubble is visitor-centric (their own message =
// "outbound"/right, an agent reply = "inbound"/left). fromServer() flips it.
interface ServerMessage {
  id?: string;
  direction?: string;
  content?: string;
  sent_at?: string;
  media_url?: string | null;
  attachments?: WidgetAttachment[] | null;
}

